const CAPACITY = 5;          // max burst of attempts per key
const REFILL_PER_SEC = 1 / 12; // ~5 attempts per minute sustained
const buckets = new Map();

function rateLimitLogin(req, res, next) {
  const key = req.ip;
  const now = Date.now();
  const b = buckets.get(key) ?? { tokens: CAPACITY, last: now };

  b.tokens = Math.min(CAPACITY, b.tokens + ((now - b.last) / 1000) * REFILL_PER_SEC);
  b.last = now;

  if (b.tokens < 1) {
    buckets.set(key, b);
    const retry = Math.ceil((1 - b.tokens) / REFILL_PER_SEC);
    res.set("Retry-After", String(retry));
    return res.status(429).json({ error: "Too many login attempts" });
  }

  b.tokens -= 1;
  buckets.set(key, b);
  next();
}

// Evict idle buckets so the map can't grow without bound
setInterval(() => {
  const cutoff = Date.now() - 10 * 60 * 1000;
  for (const [k, b] of buckets) if (b.last < cutoff) buckets.delete(k);
}, 60 * 1000).unref();

module.exports = rateLimitLogin;
