function createRateLimiter({ capacity = 5, refillPerSec = 5 / 60, maxKeys = 10_000 } = {}) {
  const buckets = new Map(); // key -> { tokens, last }

  return function rateLimit(req, res, next) {
    const key = req.ip;
    const now = Date.now();

    let b = buckets.get(key);
    if (!b) {
