      const retryAfter = Math.ceil((1 - b.tokens) / refillPerSec);
      res.set("Retry-After", String(retryAfter));
      return res.status(429).json({ error: "Too many login attempts. Try again later." });
    }

    b.tokens -= 1;
    next();
  };
}

